local function Log(...)
  pcall(funcLuaCommand, C.LOG, "contact_map", ...)
end

-- OPEN TRACE (perf, diagnostics). The log has a 343 ms HITCH ~1 s after the open, once
-- the script's 2.3 s were gone from OnInit: engine work with no Lua call, its cause not in the log. For the first
-- OT.FRAMES frames of the screen, every frame with an event (layer instances set up, by layer; a texture / face that
-- came in; a redraw; the input anchor) and every OT.EVERY frames logs "contact_map open trace f<n> ...", so the next
-- HITCH line falls between two of them and names the frame's work. At most OT.MAX lines per open.
local OT = {f = 0, FRAMES = 150, EVERY = 10, MAX = 40, lines = 0, setup = {}, ev = {}, names = nil}
local function OtNote(what)
  if OT.f <= OT.FRAMES then
    OT.ev[#OT.ev + 1] = what
  end
end

local function Call(cmd, ...)
  local r = table.pack(pcall(funcLuaCommand, cmd, ...))
  if not r[1] then
    return nil
  end
  return table.unpack(r, 2, r.n)
end

local function Int(v)
  if type(v) ~= "number" then
    return 0
  end
  return math.floor(v + 0.5)
end

local function Hide(layer, idx)
  funcLuaMenuCommand(C.LAYER_VISIBLE, layer, idx, false)
  funcLuaMenuCommand(C.POS, layer, -4000, 4000, 0, idx)
end

local function Ask(text)
  funcLuaMenuCommand(C.MENU_ACTIVE, MENU, false)
  funcLuaCommand(C.MSG_OPEN, text, 0, 0, 0, 0, 0, false)
  funcLuaCommand(C.MSG_KIND, 2, 0)
  coroutine.yield()
  local r = -1
  while r == nil or r < 0 do
    r = funcLuaCommand(C.MSG_RESULT)
    coroutine.yield()
  end
  while not funcLuaCommand(C.MSG_DONE) do
    coroutine.yield()
  end
  funcLuaMenuCommand(C.MENU_ACTIVE, MENU, true)
  return r == 0
end

local function Message(text)
  funcLuaMenuCommand(C.MENU_ACTIVE, MENU, false)
  funcLuaCommand(C.MSG_OPEN, text, 0, 0, 0, 0, 0, false)
  funcLuaCommand(C.MSG_KIND, 1, 0)
  coroutine.yield()
  while funcLuaCommand(C.MSG_BUSY) do
    coroutine.yield()
  end
  while not funcLuaCommand(C.MSG_DONE) do
    coroutine.yield()
  end
  funcLuaMenuCommand(C.MENU_ACTIVE, MENU, true)
end

local function Close(result)
  funcLuaCommand(C.P_CLEAR, KEY_RESULT)
  funcLuaCommand(C.P_SET, KEY_RESULT, 0, result, 1)
  funcLuaMenuCommand(C.MENU_ACTIVE, MENU, false)
  funcLuaCommand(C.CLOSE_MENU, MENU)
end

local function StartCo(fn, arg)
  if evt_co ~= nil then
    return
  end
  evt_co = coroutine.create(fn)
  local ok, err = coroutine.resume(evt_co, arg)
  if not ok then
    PRINT("vrfw_contact_map_menu: " .. tostring(err))
    Log("error", tostring(err))
    evt_co = nil
    funcLuaMenuCommand(C.MENU_ACTIVE, MENU, true)
  elseif coroutine.status(evt_co) == "dead" then
    evt_co = nil
  end
end

-- EVT_PointerNew(): a pointer helper for menus that draw their own selectable items (docs/game/ui/mouse-support.md §5).
-- Mouse and VR's free cursor (the stick-driven «virtual mouse», CMND_SET_ENABLE_FREE_CURSOR_FOR_VIRTUAL_MOUSE) are
-- the same pointer: the engine's pointer position (558229292, screen px, y down) is read every frame and any change
-- (or the engine's «mouse moved», 3272825600) puts the menu in pointer mode; a menu arrow (CMD_UP/DOWN/LEFT/RIGHT)
-- ends it. The menu declares its zones each time it draws, from the same positions it draws with:
--   P.Begin()                              forget the zones of the last drawing
--   P.Rect(x, y, w, h, id[, edge])         top-left + size, screen px (y down)
--   P.Box(cx, cy, hw, hh, id[, edge])      centre + half sizes, screen px (y down)
--   P.Inst(layer, idx, hw, hh, id[, edge]) around a layer instance's global position (read at hit-test time)
--   (edge = -1 / 1: a scroll band; hovering it scrolls every P.REPEAT frames: ev.edge)
-- The last zone declared wins (popups / buttons drawn over cards). Per frame (Step): local ev = P.Poll() with
--   ev.moved   the pointer moved (pointer mode on)          ev.hot / ev.changed  zone id under the pointer / it changed
--   ev.click   id clicked (mouse left button, or Accept / the free cursor's A in pointer mode) on a zone
--   ev.miss    a mouse click on no zone (do nothing; Enter / A there = the menu's key Accept, pointer mode off)
--   ev.wheel   -1 up / 1 down (CMD_EVT_WHEEL_*)
--   ev.edge    -1 / 1 from a scroll band                     ev.keys   a menu arrow was pressed (pointer mode off)
--   ev.hover   the zone under the pointer, only on a frame the pointer MOVED (or was clicked): hover by movement only,
--              so a redraw / scroll / camera move under a resting pointer never re-selects (retail behaviour)
-- P.KeyStep(): the menu moved its selection itself (its own key callbacks, a polled stick / D-pad the arrows above do
-- not see): pointer mode off and the resting position taken as the baseline, so the pad owns the selection until the
-- pointer really moves again or clicks (a resting mouse would otherwise pin the selection under it).
-- Hover = move the selection to ev.hot with the keyboard highlight; ev.click = select it and decide. The menu's own
-- Accept callbacks (OnEnter / OnDecideFocus / a polled CMD_ENTER) return early while P.Owns(): in pointer mode the
-- click belongs to the pointer, so an item not under it is never activated. Zones are only declared for pickable,
-- shown items (never hidden ones). P.Forget() after a redraw under a still pointer re-focuses the zone beneath it.
EVT_PointerNew = EVT_PointerNew or function()
  local P = {zones = {}, on = false, x = nil, y = nil, hot = nil, prev = {}, edge_t = 0, REPEAT = 10}
  local MOVED, POS, GPOS, CHECK, CTRL = 3272825600, 558229292, 4002164178, 4265778440, 1332654303
  local LEFT, CLICK = 218912913 --[[CMD_EVT_MOUSE_LEFT]], 1651523701 --[[CMD_ENTER_CLICK]]
  local W_UP, W_DOWN = 1942756954 --[[CMD_EVT_WHEEL_UP]], 1623431741 --[[CMD_EVT_WHEEL_DOWN]]
  local NAV = {1197218715, 3259546669, 2765147006, 2075023265} -- CMD_UP / DOWN / LEFT / RIGHT
  local CTRLS = {CTRL, 2748927068 --[[analog-move control: the stick's menu moves]]}
  local function M(cmd, ...)
    local ok, a, b = pcall(funcLuaMenuCommand, cmd, ...)
    if ok then return a, b end
    return nil
  end
  local function In(cmd, ctrl)
    local ok, r = pcall(funcLuaCommand, CHECK, ctrl or CTRL, cmd)
    return ok and r == true
  end
  local function Edge(cmd, ctrl)
    local key = ctrl and (tostring(ctrl) .. ":" .. tostring(cmd)) or cmd
    local now = In(cmd, ctrl)
    local was = P.prev[key]
    P.prev[key] = now
    return now and not was
  end
  function P.Begin()
    P.zones = {}
  end
  function P.Rect(x, y, w, h, id, edge)
    P.zones[#P.zones + 1] = {x, y, x + w, y + h, id = id, edge = edge}
  end
  function P.Box(cx, cy, hw, hh, id, edge)
    P.zones[#P.zones + 1] = {cx - hw, cy - hh, cx + hw, cy + hh, id = id, edge = edge}
  end
  function P.Inst(layer, idx, hw, hh, id, edge)
    P.zones[#P.zones + 1] = {layer = layer, idx = idx, hw = hw, hh = hh, id = id, edge = edge}
  end
  function P.Pos()
    local x, y = M(POS)
    if type(x) == "number" and type(y) == "number" then return x, y end
    return nil
  end
  function P.At(x, y)
    if x == nil then x, y = P.x, P.y end
    if x == nil then return nil end
    for i = #P.zones, 1, -1 do
      local z = P.zones[i]
      if z.layer ~= nil then
        local gx, gy = M(GPOS, z.layer, z.idx)
        if type(gx) == "number" and type(gy) == "number" and math.abs(x - gx) <= z.hw and math.abs(-y - gy) <= z.hh then
          return z
        end
      elseif x >= z[1] and x < z[3] and y >= z[2] and y < z[4] then
        return z
      end
    end
    return nil
  end
  -- the Accept being pressed now is a pointer click: the mouse button, or Accept / A in pointer mode ON an item
  -- (Enter / A with the pointer resting on empty space is a key Accept on the current selection)
  function P.Owns()
    return In(LEFT) or (P.on and In(CLICK) and P.At() ~= nil)
  end
  -- forget the hovered zone: the next Poll reports the zone under a still pointer as changed (after a redraw)
  function P.Forget()
    P.hot = nil
  end
  function P.KeyStep()
    P.on, P.hot = false, nil
    local x, y = P.Pos()
    if x ~= nil then P.x, P.y = x, y end
  end
  function P.Reset()
    P.zones, P.on, P.hot, P.prev, P.edge_t = {}, false, nil, {}, 0
    P.x, P.y = P.Pos()
    -- a press / wheel / arrow held from the screen before is no click, no scroll, no key
    for _, c in ipairs({LEFT, CLICK, W_UP, W_DOWN}) do Edge(c) end
    for _, ctrl in ipairs(CTRLS) do
      for _, c in ipairs(NAV) do Edge(c, ctrl) end
    end
  end
  function P.Poll()
    local ev = {}
    local x, y = P.Pos()
    if x ~= nil then
      local moved = M(MOVED) == true
      if not moved and P.x ~= nil and (math.abs(x - P.x) > 1 or math.abs(y - P.y) > 1) then
        moved = true    -- the free cursor (stick) moves the pointer without the mouse's «moved» flag
      end
      P.x, P.y = x, y
      if moved then
        P.on, ev.moved = true, true
      end
    end
    for _, ctrl in ipairs(CTRLS) do
      for _, c in ipairs(NAV) do
        if Edge(c, ctrl) then
          ev.keys = true
        end
      end
    end
    if ev.keys and not ev.moved then
      P.on = false
    end
    local left, click = Edge(LEFT), Edge(CLICK)
    if left then
      P.on = true
    end
    local z = P.on and P.At() or nil
    local id = z and z.id or nil
    ev.changed = id ~= P.hot
    P.hot, ev.hot = id, id
    if z ~= nil and (ev.moved or left) then
      ev.hover = id
    end
    if left then
      if z ~= nil then
        ev.click = id
      else
        ev.miss = true                 -- a mouse click on empty space: nothing
      end
    elseif click and P.on then
      if z ~= nil then
        ev.click = id
      else
        P.on, P.hot = false, nil       -- Enter / A on empty space: the menu's key Accept takes it (selection kept)
      end
    end
    if In(W_DOWN) then
      ev.wheel = 1
    elseif In(W_UP) then
      ev.wheel = -1
    end
    if z ~= nil and z.edge ~= nil then
      P.edge_t = P.edge_t - 1
      if P.edge_t <= 0 then
        ev.edge, P.edge_t = z.edge, P.REPEAT
      end
    else
      P.edge_t = 0
    end
    return ev
  end
  return P
end
local Ptr = EVT_PointerNew()

-- EVT_CharaModelNew(layer[, opts]): a player's 3D model in a menu, the retail shop's way (docs/framework/contact-map.md
-- §8; the Oficina de fichajes, office_look ofl_buy_1.lua B/F/G, does the same on shop01_01_list_base). `layer` = a layer
-- whose object carries a CMenuCharaModelComponent (retail shop01_01_list_base, or an object derived from it); model
-- slot 0. Flicker-free and never in T-pose: one build per player, a new build only once the last one is complete, the
-- model hidden until the component says it is complete (1583438030) for `settle` frames.
--   M.Show(pid)   the model of chara_param `pid` (built once; the same player again = just shown)
--   M.Hide()      hidden (a build under way stays hidden when it completes)
--   M.Step()      every frame (Step)
--   M.Release()   the model released (a list that changes its players frees the old ones)
--   M.Ok()        false when the layer has no model component (nothing was ever built): draw something else
-- opts: shadow = the 3D shadow layer (retail mainmenu01_08_chara_3d_shadow), pose (retail shop 2328706751), uniform (0 =
-- his own), look (look flags, 0), settle (2), min (6), max (120), log = function(...) for the first lines,
-- kit = function(pid) -> uniform, flags: the kit of that player (uniform 0 = `uniform`; flags 2 = the keeper shirt),
-- asked once per build (the contact map: his own team's kit, CMND_VRFW_CONTACT_KIT),
-- slot = the component's model slot (0; a component with m_useObjectNum > 1 holds one model per slot, as the retail
-- shop's 4 and the Victory Road top's 11), key = that slot's model key (the slot number, as retail),
-- bodies = {[body type] = true} the body types the pose has (menu_chara_model_pose_config; the framework's
-- CMND_VRFW_MODEL_POSE_BODIES). CRASH GUARD (nie.exe+0x1114F94 reads 0x4C): the pose command
-- (2450020144) looks the pose up for the chara's body type (CMND_GET_CHARA_INFO(chara, 3)) and dereferences the result
-- unchecked: a body type the pose does not list kills the game. Such a player gets no model (log «skip body»); with no
-- `bodies` the pose command is never sent.
EVT_CharaModelNew = EVT_CharaModelNew or function(layer, opts)
  opts = opts or {}
  local M = {pid = nil, chara = nil, pend = nil, build = nil, hide_build = false, logs = 0, failed = false,
    SHADOW = opts.shadow or 858725131 --[[mainmenu01_08_chara_3d_shadow]], POSE = opts.pose or 2328706751,
    SETTLE = opts.settle or 2, MIN = opts.min or 6, MAX = opts.max or 120, SLOT = opts.slot or 0}
  M.KEY = opts.key or M.SLOT
  local function MC(cmd, ...)
    local ok, a, b = pcall(funcLuaMenuCommand, cmd, ...)
    if ok then return a, b end
    return nil
  end
  local function Log(...)
    if opts.log ~= nil and M.logs < 12 then
      M.logs = M.logs + 1
      pcall(opts.log, "model", ...)
    end
  end
  local function Visible(on)
    local h = MC(3895705890, layer, 0, M.SLOT)
    if type(h) == "number" and h ~= 0 then
      pcall(funcLuaCommand, 1890282463, h, on)
    end
  end
  local function Ready()
    return MC(1583438030, layer, 0, M.SLOT) == true
  end
  local function Loading(chara)
    local ok, l = pcall(funcLuaCommand, 2475005551, chara)
    return ok and l == true
  end
  local function BuildDone()
    return M.build == nil or M.build.done
  end
  -- retail shop_menu_buy SetupCharaModel(0, chara, uniform, motion, look, pose, 0, false)
  -- the chara's body type (retail SetupCharaModel: CMND_GET_CHARA_INFO(chara, 3)); 0 when the game has none
  local function BodyType(chara)
    local ok, has, v = pcall(funcLuaCommand, 4060384944 --[[CMND_GET_CHARA_INFO]], chara, 3, 0)
    if ok and has == true and type(v) == "number" then
      return v
    end
    return 0
  end
  local function Setup(chara, pid, motion, n, uniform, flags)
    MC(59611540, layer, 0, chara, M.SLOT)
    MC(186863317 --[[CMND_SET_SCN_CHARA_REGIST_TYPE]], layer, 0, 4, M.SLOT)
    MC(3290636356, layer, 0, uniform, motion, flags, M.SLOT)
    MC(4219344099 --[[CMND_SET_CHARA_MODEL_SHADOW?]], layer, 0, M.SHADOW, M.SLOT, M.SLOT)
    MC(2232914067 --[[CMND_CHARA_MODEL_CHANGE]], layer, 0, 0, 9, M.SLOT, M.KEY)
    if opts.bodies ~= nil and opts.bodies[n] then   -- only a body type the pose lists (see CRASH GUARD above)
      MC(2450020144, layer, 0, M.POSE, n, M.SLOT)
    end
  end
  local function BuildStep()
    local B = M.build
    if B == nil or B.done then
      return
    end
    B.n = B.n + 1
    if not Ready() then
      B.seen, B.ok = true, 0
    elseif B.seen or B.n >= M.MIN then
      B.ok = B.ok + 1
    end
    if B.ok >= M.SETTLE or B.n >= M.MAX then
      B.done = true
      if not B.seen and B.ok < M.SETTLE then
        M.failed = true
      end
      Log("ready", B.n, tostring(B.seen), tostring(B.ok >= M.SETTLE))
    end
  end
  local function PendStep()
    local P = M.pend
    if P == nil then
      if M.hide_build then
        Visible(false)
        M.hide_build = not BuildDone()
      end
      return
    end
    M.hide_build = false
    P.n = P.n + 1
    if not P.built then
      if P.n < M.MAX and (not BuildDone() or Loading(P.chara)) then
        Visible(false)
        return
      end
      local ok, err = pcall(Setup, P.chara, P.pid, P.motion, P.body, P.uniform, P.flags)
      Visible(false)
      P.built, P.n = true, 0
      M.build = {n = 0, seen = false, ok = 0, done = false}
      M.pid, M.chara = P.pid, P.chara
      Log("build", P.pid, P.chara, P.motion, string.format("uniform 0x%08X flags %d", P.uniform, P.flags), tostring(ok),
        tostring(err))
      return
    end
    if not BuildDone() then
      Visible(false)
      return
    end
    Visible(true)
    M.pend = nil
    Log("shown", P.pid, P.n)
  end
  function M.Ok()
    return not M.failed
  end
  function M.Hide()
    M.pend = nil
    M.hide_build = not BuildDone()
    if M.pid ~= nil then
      Visible(false)
    end
  end
  -- the slot's model released (retail shop ResetCharaModel): nothing shown, its resources freed
  function M.Release()
    M.pend, M.hide_build = nil, false
    if M.pid ~= nil then
      Visible(false)
      MC(59611540, layer, 0, 0, M.SLOT)
      -- the slot's own key: without it the change reached model key 0 (another menu's model, e.g. the board's caravan)
      MC(2232914067 --[[CMND_CHARA_MODEL_CHANGE]], layer, 0, 0, 9, M.SLOT, M.KEY)
    end
    M.pid, M.chara, M.build = nil, nil, nil
  end
  function M.Show(pid)
    local P = M.pend
    if P ~= nil and P.pid == pid then
      return
    end
    if P == nil and M.pid == pid then
      if BuildDone() then
        Visible(true)
      else
        M.pend = {pid = pid, chara = M.chara, n = 0, built = true}
      end
      return
    end
    local ok, chara = pcall(funcLuaCommand, 347353059 --[[chara of chara_param]], pid)
    if not ok or type(chara) ~= "number" or chara == 0 then
      Log("none", pid)
      M.Hide()
      return
    end
    local motion = 1
    local ok2, has, v = pcall(funcLuaCommand, 4060384944 --[[CMND_GET_CHARA_INFO]], pid, 21)
    if ok2 and has == true and type(v) == "number" and v ~= 0 then
      motion = v
    end
    local body = BodyType(chara)
    if opts.bodies == nil or not opts.bodies[body] then
      Log("skip body", pid, chara, body, tostring(opts.bodies ~= nil))
      M.Hide()
      return
    end
    -- the kit: the caller's per player (opts.kit), else opts.uniform / opts.look
    local uniform, flags = opts.uniform or 0, opts.look or 0
    if opts.kit ~= nil then
      local okk, u, f = pcall(opts.kit, pid)
      if okk and type(u) == "number" and u ~= 0 then
        uniform = u
      end
      -- the look bits the caller asks (2 the keeper shirt, 16 a coach's, 32 a manager's own clothes; as the retail
      -- team dock's model flags) added to the screen's own
      if okk and type(f) == "number" then
        for _, bit in ipairs({2, 16, 32}) do
          if math.floor(f / bit) % 2 == 1 and math.floor(flags / bit) % 2 == 0 then
            flags = flags + bit
          end
        end
      end
    end
    Visible(false)
    M.pend = {pid = pid, chara = chara, motion = motion, body = body, uniform = uniform, flags = flags, n = 0,
      built = false}
    PendStep()
  end
  function M.Step()
    BuildStep()
    PendStep()
  end
  return M
end
local Model = nil       -- the panel's 3D player model (EVT_CharaModelNew on vrfw_cm_model; made in OnInit)

local function Text(id)
  local ok, s = pcall(funcLuaCommand, C.TEXT_GET, id)
  if ok and type(s) == "string" then
    return s
  end
  return ""
end

local function Fmt(id, ...)
  local ok, s = pcall(string.format, Text(id), ...)
  if ok then
    return s
  end
  return Text(id)
end

-- a map's name: its series' name when the map has one (team pages of a Chronicle route), else its title row
-- team pages: series names, «owns any card of the character» answers (a global: the main chunk is at its 200 locals)
CmPages = {series = {}, own = {}}
function CmPages.MapTitle(m)
  local sid = m and Int(m.series) or 0
  if sid ~= 0 then
    if CmPages.series[sid] == nil then
      local ok, okc, s = pcall(funcLuaMenuCommand, 964991930 --[[CMND_GET_CHARA_SERIES_INFO]], 1, sid)
      CmPages.series[sid] = (ok and okc and type(s) == "string" and s ~= "") and s or false
    end
    if CmPages.series[sid] then
      return CmPages.series[sid]
    end
  end
  return Text(m and m.title or 0)
end

-- the recruit currency's name: the set's RecruitCurrencyTitle row, else the item's own name (as the game shows it,
-- renamed by any mod)
function CmPages.CurrencyName()
  local s = SET ~= nil and Text(SET.rct) or ""
  if s == "" and SET ~= nil and Int(SET.rc) ~= 0 then
    local ok, name = pcall(funcLuaCommand, 1883585771 --[[item name (item, 0)]], SET.rc, 0)
    if ok and type(name) == "string" then
      s = name
    end
  end
  return s
end

-- a zone's name: its label (a team page: the team's name) when served, else its title row
function CmPages.ZoneTitle(z)
  if z ~= nil and type(z.label) == "string" and z.label ~= "" then
    return z.label
  end
  return Text(z and z.title or 0)
end

local function Place(layer, idx, x, y)
  funcLuaMenuCommand(C.POS, layer, x, -y, 0, idx)
end

local function SetColour(layer, idx, c)
  funcLuaMenuCommand(C.PRIM_COLOR, layer, idx, MESH_QUAD, c[1], c[2], c[3])
end

-- a sprite on a quad; the sprite command's answer (false: the atlas is not there)
local function QuadTex(layer, idx, texCrc, spriteCrc, x, y, w, h)
  funcLuaMenuCommand(C.LAYER_VISIBLE, layer, idx, true)
  funcLuaMenuCommand(C.SCALE, layer, w / Q, h / Q, 1, idx)
  local ok = funcLuaMenuCommand(C.SPRITE, layer, texCrc, spriteCrc, NODE_QUAD, 0, idx)
  Place(layer, idx, x, y)
  local pt = plain_tint[layer]
  if pt ~= nil and pt[idx] ~= nil then   -- the slot held a tinted plain shape: back to the sprite's own colours
    pt[idx] = nil
    SetColour(layer, idx, COLOUR.WHITE)
  end
  return ok
end

-- a colour on a quad; on a plain fallback shape it is multiplied by the role's own colour (the state stays readable)
local function Tint(layer, idx, c)
  local pt = plain_tint[layer] and plain_tint[layer][idx]
  if pt ~= nil then
    c = {c[1] * pt[1], c[2] * pt[2], c[3] * pt[3]}
  end
  SetColour(layer, idx, c)
end

local function Line(layer, idx, s, x, y, scale)
  if s == nil or s == "" then
    Hide(layer, idx)
    return
  end
  funcLuaMenuCommand(C.LAYER_VISIBLE, layer, idx, true)
  funcLuaMenuCommand(C.SCALE, layer, scale or 1, scale or 1, 1, idx)
  funcLuaMenuCommand(C.TEXT, layer, TEXT_ON, s, idx)
  funcLuaMenuCommand(C.TEXT_VISIBLE, layer, TEXT_ON, true, idx)
  Place(layer, idx, x - TEXT_DX * (scale or 1), y)
end

-- a texture loaded on demand: its crc, or false while loading, or nil when it never came in
local function Tex(path)
  if path == nil or path == "" or tex_frames[path] == -1 then
    return nil
  end
  if not tex_asked[path] then
    tex_asked[path] = true
    tex_frames[path] = 0
    funcLuaMenuCommand(C.LOAD_TEX, path)
  end
  local tc = CRC32(path)
  if funcLuaCommand(C.TEX_LOADING, tc) == true then
    tex_wait = true
    return false
  end
  return tc
end

-- the sprite of art role `role` (a mod's declaration, its atlas loaded on demand: hidden while it loads, Step redraws)
-- or, undeclared / not there, the role's plain fallback shape tinted with its colour: never a missing sprite
local function Quad(layer, idx, role, x, y, w, h)
  local a = art[role]
  if a ~= nil then
    local tc = Tex(a.atlas)
    if tc == false then
      Hide(layer, idx)
      return
    end
    if tc ~= nil and QuadTex(layer, idx, tc, a.crc, x, y, w, h) ~= false then
      return
    end
  end
  local f = FALLBACK[role] or FALLBACK_ANY
  local tc, sc = VRFW_ScreenArt.Plain(f[1])
  QuadTex(layer, idx, tc, sc, x, y, w, h)
  plain_tint[layer] = plain_tint[layer] or {}
  plain_tint[layer][idx] = f[2]
  SetColour(layer, idx, f[2])
end

local function BustLayer(layer)
  if layer == L_FACE then
    return L_BUST
  elseif layer == L_ICON then
    return L_BUSTICON
  end
  return nil
end

local function HideBust(layer, idx)
  if layer ~= nil then
    Hide(layer, idx)
    BUST.wait[layer .. ":" .. idx] = nil
  end
end

-- the game's miniface + kit bust of chara_param `card`, centred at (x, y), `size` px high
local function DrawBust(layer, idx, card, x, y, size)
  local s = size / BUST.RH
  funcLuaMenuCommand(C.SCALE, layer, s, s, 1, idx)
  funcLuaMenuCommand(C.POS, layer, x - BUST.OX * s, -y - BUST.OY * s, 0, idx)
  BUST.key[layer] = BUST.key[layer] or {}
  if BUST.key[layer][idx] ~= card then
    for _, m in ipairs(BUST.HIDE) do
      funcLuaMenuCommand(C.MESH_VISIBLE, layer, CRC32(m), false, idx)
    end
    for _, m in ipairs(BUST.HIDE_NODES) do
      funcLuaMenuCommand(C.NODE_VISIBLE, layer, CRC32(m), false, idx)
    end
    funcLuaMenuCommand(C.NAME_VISIBLE, layer, BUST.NAME, false, idx)
    local mask_tex, mask_sprite = VRFW_ScreenArt.Plain("mask")
    local blank_tex, blank_sprite = VRFW_ScreenArt.Plain("blank")
    local okm = funcLuaMenuCommand(C.SPRITE, layer, mask_tex, mask_sprite, BUST.T_MASK, 0, idx)
    funcLuaMenuCommand(C.SPRITE, layer, blank_tex, blank_sprite, BUST.T_COLOR, 0, idx)
    local tk = layer .. ":" .. idx
    if okm == false and (BUST.tries[tk] or 0) < BUST.MASK_TRIES then
      BUST.tries[tk] = (BUST.tries[tk] or 0) + 1   -- the atlas is not in yet: swap again next draw
      funcLuaMenuCommand(C.LAYER_VISIBLE, layer, idx, false)
      return
    end
    BUST.tries[tk] = nil
    funcLuaMenuCommand(C.RESET_FACE, layer, idx, BUST.TEX)
    local ok, chara = pcall(funcLuaCommand, C.CHARA_OF_PARAM, card)
    if not ok or type(chara) ~= "number" or chara == 0 then
      chara = card
    end
    pcall(SetDisableForceCharaInvalidUseTarget)
    funcLuaMenuCommand(C.FACE, layer, idx, false, BUST.MESH, BUST.TEX, 0, 0, chara, 0, false, true)
    pcall(SetEnableForceCharaInvalidUseTarget)
    BUST.key[layer][idx] = card
  end
  local loading = funcLuaMenuCommand(C.FACE_LOADING, layer, idx) == true
  funcLuaMenuCommand(C.MESH_VISIBLE, layer, BUST.MESH, not loading, idx)
  BUST.wait[layer .. ":" .. idx] = loading and {layer, idx} or nil
  funcLuaMenuCommand(C.LAYER_VISIBLE, layer, idx, true)
end

-- the busts still loading: shown once their face is in (Step)
local function BustStep()
  for k, w in pairs(BUST.wait) do
    if funcLuaMenuCommand(C.FACE_LOADING, w[1], w[2]) ~= true then
      funcLuaMenuCommand(C.MESH_VISIBLE, w[1], BUST.MESH, true, w[2])
      BUST.wait[k] = nil
      OtNote("face in")
    end
  end
end

local function DrawFace(layer, idx, face, x, y, size)
  local card = 0
  if type(face) == "table" then
    card = Int(face.card)
    face = face.face
  end
  local bl = BustLayer(layer)
  if card ~= 0 and bl ~= nil then
    Hide(layer, idx)
    DrawBust(bl, idx, card, x, y, size)
    return
  end
  HideBust(bl, idx)
  if face == nil or face == "" then
    Quad(layer, idx, "icon_unknown", x, y, size, size)
    return
  end
  local tc = Tex(FACE_DIR .. face .. "_l.g4tx")
  if tc == false then
    Hide(layer, idx)              -- still loading: Step redraws
  elseif tc == nil then
    Quad(layer, idx, "icon_unknown", x, y, size, size)
  else
    QuadTex(layer, idx, tc, CRC32(face .. "_1_l00"), x, y, size, size)
  end
end

-- ---- data -----------------------------------------------------------------------------------------------------------
local function LoadSet(set)
  lang = Int(Call(C.LANG))
  local s = Call(C.CM_MAPS, set, lang)
  if type(s) ~= "table" or type(s.maps) ~= "table" or #s.maps == 0 then
    return nil
  end
  VIEW_ALL.on = s.reveal == true
  return s
end

-- the record: the chara_param ids signed on the map (key "contact.cards.<map>"). It was the node numbers
-- ("contact.<map>"), which a rebuilt map gives to other tiles (a tile two steps from the start looked signed); that
-- old key is not read any more
local function RecordKey()
  return "contact.cards." .. MAP.key
end

local function LoadRecord()
  signed = {}
  local cards = {}
  local v = Call(C.SAVE_GET, OWNER, RecordKey(), "")
  for x in string.gmatch(type(v) == "string" and v or "", "%d+") do
    cards[tonumber(x)] = true
  end
  for i, n in ipairs(MAP.nodes) do
    if n.kind == "player" and cards[Int(n.card)] then
      signed[i] = true
    end
  end
end

local function SaveRecord()
  local t = {}
  for k in pairs(signed) do
    local n = MAP.nodes[k]
    if n ~= nil and Int(n.card) ~= 0 then
      t[#t + 1] = Int(n.card)
    end
  end
  table.sort(t)
  Call(C.SAVE_SET, OWNER, RecordKey(), table.concat(t, ","), 1)
end

-- the cards the set's Exclude took off the map (m.excl) are not counted: an older record may still name one
local function MapSigned(m)
  local v = Call(C.SAVE_GET, OWNER, "contact.cards." .. m.key, "")
  local skip = {}
  for _, c in ipairs(type(m.excl) == "table" and m.excl or {}) do
    skip[Int(c)] = true
  end
  local n = 0
  for x in string.gmatch(type(v) == "string" and v or "", "%d+") do
    if not skip[tonumber(x)] then
      n = n + 1
    end
  end
  return n
end

local function ReqsMet(node)
  return #VRFW_Recruit.Missing(node.reqs) == 0
end

-- a node with `cards` (team pages: every card of the character) counts as signed when any of them is in the club;
-- the answer is kept until the map opens again (CmPages.own)
local function IsSigned(i)
  local n = MAP.nodes[i]
  if signed[i] == true and not (type(n.cards) == "table" and #n.cards > 0) then
    return true
  end
  if n.kind ~= "player" then
    return false
  end
  if type(n.cards) == "table" and #n.cards > 0 then
    if CmPages.own[i] == nil then
      CmPages.own[i] = VRFW_Recruit.OwnedAny(n.cards) > 0
    end
    return CmPages.own[i]
  end
  return VRFW_Recruit.Owned(n.card) > 0
end

-- the strict order (IE's Connection Map): acquired / open per tile, to a fixed point
local function NetState()
  acquired, opened = {}, {}
  local nodes = MAP.nodes
  local changed = true
  local guard = 0
  while changed and guard < #nodes + 2 do
    changed, guard = false, guard + 1
    for i, n in ipairs(nodes) do
      if not opened[i] then
        local o = n.kind == "start" or MAP.strict == false   -- not strict: every tile open
        for _, l in ipairs(n.links) do
          if acquired[l] then
            o = true
            break
          end
        end
        if o then
          opened[i], changed = true, true
        end
      end
      if opened[i] and not acquired[i] then
        local a = false
        if n.kind == "start" or n.kind == "open" then
          a = true
        elseif n.kind == "gate" then
          a = ReqsMet(n)
        else
          a = IsSigned(i)
        end
        if a then
          acquired[i], changed = true, true
        end
      end
    end
  end
  VIEW_ALL.real = opened
  if VIEW_ALL.on then                 -- view everything: every tile drawn open (the real ones stay in VIEW_ALL.real)
    local all = {}
    for i in ipairs(nodes) do
      all[i] = true
    end
    opened = all
  end
end

local function Price(node)
  return node.price or 0
end

local function CanAfford(node)
  return VRFW_Recruit.Wallet(CmPages.PriceOf(node)) >= Price(node)
end

-- a player's state: "done", "ready", "missing", "locked"
local function State(i)
  local n = MAP.nodes[i]
  if MAP.kind == "network" and not opened[i] then
    return "locked"
  end
  if IsSigned(i) then
    return "done"
  end
  if MAP.kind == "network" and VIEW_ALL.on and not VIEW_ALL.real[i] then
    return "missing"                  -- view everything: drawn, never "can be signed now" before its real turn
  end
  if ReqsMet(n) and CanAfford(n) then
    return "ready"
  end
  return "missing"
end

local function ZoneMembers(z)
  local out = {}
  for i, n in ipairs(MAP.nodes) do
    if n.kind == "player" and n.zone == z then
      out[#out + 1] = i
    end
  end
  return out
end

local function ZoneSigned(z)
  local k = 0
  for i, n in ipairs(MAP.nodes) do
    if n.kind == "player" and n.zone == z and IsSigned(i) then
      k = k + 1
    end
  end
  return k
end

local function ItemTitle(id)
  for _, it in ipairs(MAP and MAP.items or {}) do
    if it.item == id then
      return Text(it.title)
    end
  end
  if SET ~= nil and id == SET.ic then
    return Text(SET.ict)
  end
  if SET ~= nil and id == SET.rc then
    return CmPages.CurrencyName()
  end
  return "#" .. tostring(id)
end

local function ReqLines(node)
  local out = {}
  for _, r in ipairs(node.reqs or {}) do
    local have = VRFW_Recruit.Have(r)
    local mark = have >= (r.count or 1) and MARK_ON or MARK_OFF
    local count = "  " .. tostring(math.min(have, r.count or 1)) .. "/" .. tostring(r.count or 1)
    if r.kind == "player" and (r.level or 0) > 1 then
      out[#out + 1] = mark .. Fmt(T.REQ_PLAYER_LEVEL, CmClip((r.name or "") ~= "" and r.name or Text(T.UNKNOWN), INFO.CLIP - 14),
        r.level)
    elseif r.kind == "player" then
      -- the name, cut so the count stays visible
      out[#out + 1] = mark .. CmClip((r.name or "") ~= "" and r.name or Text(T.UNKNOWN), INFO.CLIP - 8) .. count
    elseif r.kind == "item" then
      local title = (r.title ~= nil and r.title ~= 0) and Text(r.title) or ItemTitle(r.id)
      out[#out + 1] = mark .. CmClip(title, INFO.CLIP - 8) .. count
    elseif r.kind == "team_level" then
      out[#out + 1] = mark .. Fmt(T.REQ_TEAM_LEVEL, r.count or 1, have)
    elseif r.kind == "element" then
      out[#out + 1] = mark .. Fmt(T.REQ_ELEM, Text(T.ELEM[r.element] or T.UNKNOWN), r.count or 1, have)
    elseif r.kind == "position" then
      out[#out + 1] = mark .. Fmt(T.REQ_ELEM, Text(T.POS[r.position] or T.UNKNOWN), r.count or 1, have)
    elseif r.kind == "wins" then
      out[#out + 1] = mark .. Fmt(T.REQ_WINS, r.count or 1, have)
    elseif r.kind == "goals" then
      out[#out + 1] = mark .. Fmt(T.REQ_GOALS, r.count or 1, have)
    elseif r.kind == "cleared" then
      out[#out + 1] = mark .. Fmt(T.REQ_BEAT, CmClip((r.name or "") ~= "" and r.name or Text(T.UNKNOWN), INFO.CLIP - 8))
    elseif r.kind == "unlock" then
      out[#out + 1] = mark .. Fmt(T.REQ_BEAT_MORE, CmClip((r.name or "") ~= "" and r.name or Text(T.UNKNOWN), INFO.CLIP - 14))
    elseif r.kind == "trial" then
      out[#out + 1] = mark .. CmPages.TrialText(r)
    end
  end
  return out
end

