local function HideAll()
  for i = 0, N.TILE - 1 do
    Hide(L_TILE, i)
  end
  for i = 0, N.TAG - 1 do
    Hide(L_TAG, i)
  end
  for i = 0, N.FACE - 1 do
    Hide(L_FACE, i)
  end
  for i = 0, N.BUST - 1 do
    HideBust(L_BUST, i)
  end
  for i = 0, N.LINE - 1 do
    Hide(L_LINE, i)
  end
  for i = 0, N.UI - 1 do
    Hide(L_UI, i)
  end
  for i = 0, N.TITLE - 1 do
